insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_149'
from (values
('127.890.d.20.A',3,'A line mechanic reads the approved towing procedure and checks the tow bar, limits and wing walkers before moving a parked airplane. She is:','["describing proper towing and securing procedures for aircraft using approved data", "ignoring approved data", "towing by guess", "skipping chocks"]'::jsonb,0,'Towing procedure.','original'),
('127.890.d.20.A',4,'When towing an aircraft, the tow speed and turn limits come from:','["the lowest bidder", "the approved manufacturer data", "personal habit", "a friend"]'::jsonb,1,'Tow limits.','original'),
('127.890.d.20.B',3,'A mechanic services the oil, checks the oxygen bottle pressure and tops off hydraulic fluid and tire pressure on a ramp check. She is:','["ignoring servicing", "describing seats", "describing proper aircraft ground servicing, including oil, oxygen, hydraulic and pneumatic systems", "painting tires"]'::jsonb,2,'Ground servicing.','original'),
('127.890.d.20.B',4,'When servicing oxygen systems, a mechanic must keep the equipment free of:','["dust covers", "clean air", "water only", "oil and grease"]'::jsonb,3,'Oxygen clean.','original'),
('127.890.d.20.C',3,'A fueler compares the blue dye of aviation gasoline with the clear to straw color of jet fuel and notes their different smells. She is:','["differentiating between characteristics of aviation gasoline, turbine fuels and fuel additives", "ignoring fuels", "describing seats", "describing tires"]'::jsonb,0,'Fuel types.','original'),
('127.890.d.20.C',4,'Putting jet fuel in a piston engine tank can cause:','["no effect", "engine damage or failure", "a cooler engine", "better power"]'::jsonb,1,'Wrong fuel.','original'),
('127.890.d.20.D',3,'A student reads the checklist for starting an engine, the chocks, fire guard and brakes, and the steps to taxi safely. She is:','["describing seats", "describing tires", "explaining engine starting, ground operation and aircraft taxiing procedures", "ignoring starts"]'::jsonb,2,'Start and taxi.','original'),
('127.890.d.20.D',4,'Before starting an engine, a mechanic should make sure the propeller area is:','["crowded", "wet", "covered", "clear and a fire guard is posted"]'::jsonb,3,'Clear prop.','original'),
('127.890.d.20.E',3,'A technician learns the runway hold lines, taxiway signs and the right call-up for the tower before moving an aircraft on the airport. She is:','["explaining airport operation area procedures and air traffic control communications", "ignoring signs", "describing seats", "describing tires"]'::jsonb,0,'Airport ops.','original'),
('127.890.d.20.E',4,'A solid yellow line and a dashed yellow line at a hold position mean that an aircraft must:','["turn off its lights", "stop and get clearance before crossing", "park there", "speed up"]'::jsonb,1,'Hold line.','original'),
('127.890.d.20.F',3,'A mechanic compares Class A, B, C and D fire extinguishers and the fires each one is built to fight. She is:','["describing tires", "describing seats", "identifying the types and classes of fire extinguishers", "avoiding fire"]'::jsonb,2,'Extinguisher classes.','original'),
('127.890.d.20.F',4,'A tug driver sees fuel burning on the ramp after a spill. Which extinguisher class is meant for that kind of fire?','["Class A", "Class K", "Class D", "Class B"]'::jsonb,3,'Class B is for flammable liquids.','original'),
('127.890.d.20.G',3,'A shop uses shadow boards and a tool control sign-out so that every wrench is accounted for before the aircraft closes up. They are:','["analyzing the importance of proper tool and hardware use and accountability", "ignoring tools", "describing tires", "describing seats"]'::jsonb,0,'Tool control.','original'),
('127.890.d.20.G',4,'A missing tool after maintenance should be treated as:','["no problem", "a safety hazard until it is found", "trash", "a gift"]'::jsonb,1,'Missing tool.','original'),
('127.890.d.20.H',3,'A stores clerk keeps bearings in sealed bags and hangs control cables in coils so that they are not bent or dirtied. She is:','["describing tires", "ignoring storage", "describing the need for proper material handling and parts protection", "describing seats"]'::jsonb,2,'Parts protection.','original'),
('127.890.d.20.H',4,'Parts should be protected from handling damage because a nick or contamination can:','["add color", "improve strength", "reduce weight", "cause failure later"]'::jsonb,3,'Why protect.','original'),
('127.890.d.20.I',3,'A mechanic spots a solvent label, looks up the SDS and picks the right gloves and ventilation. She is:','["identifying hazardous materials, locating the appropriate safety data sheet and following proper handling", "describing seats", "describing tires", "ignoring labels"]'::jsonb,0,'SDS.','original'),
('127.890.d.20.I',4,'A safety data sheet tells a worker about a chemical''s:','["color only", "hazards, handling and first-aid steps", "price", "supplier''s address only"]'::jsonb,1,'SDS content.','original'),
('127.890.d.20.J',3,'A student reads how a loose bolt on the ramp can be sucked into an engine inlet. She is:','["describing seats", "ignoring FOD", "analyzing and describing the potential effects of foreign object damage on aircraft and personnel", "describing tires"]'::jsonb,2,'FOD effects.','original'),
('127.890.d.20.J',4,'Foreign object damage to an engine can:','["improve thrust", "cool the engine", "add weight only", "destroy blades and endanger people nearby"]'::jsonb,3,'FOD harm.','original'),
('127.890.d.21.A',3,'A technician walks the ramp in a line, picking up screws, safety wire and bits of paper before engines start. She is:','["performing a foreign object damage (FOD) control procedure", "ignoring the ramp", "skipping the walk", "painting the ramp"]'::jsonb,0,'FOD walk.','original'),
('127.890.d.21.A',4,'A good FOD walk is done:','["never", "before engine runs and aircraft movements", "once a year", "after takeoff"]'::jsonb,1,'FOD timing.','original'),
('127.890.d.21.B',3,'A mechanic checks the plug type and voltage of a ground power unit and plugs it into the aircraft''s external power receptacle. She is:','["ignoring power", "painting plugs", "connecting external power to an aircraft", "guessing voltage"]'::jsonb,2,'External power.','original'),
('127.890.d.21.B',4,'Before connecting external power, a mechanic should confirm that the unit''s:','["size matches only", "brand matches", "color matches", "voltage and polarity match the aircraft"]'::jsonb,3,'Match voltage.','original'),
('127.890.d.21.C',3,'A mechanic disconnects the ground power, installs the tow bar and checks the nose gear lock and brake release before the tug moves. She is:','["preparing an aircraft for towing", "painting the tow bar", "ignoring the gear", "guessing"]'::jsonb,0,'Prep to tow.','original'),
('127.890.d.21.C',4,'Before towing, the aircraft''s steering and gear locks should be:','["ignored", "checked or released as the approved data says", "removed entirely", "painted"]'::jsonb,1,'Gear locks.','original'),
('127.890.d.21.D',3,'A ramp marshaller crosses her wands over her head to signal an aircraft to stop. She is:','["ignoring signals", "guessing", "using appropriate hand signals for the movement of aircraft", "describing seats"]'::jsonb,2,'Hand signals.','original'),
('127.890.d.21.D',4,'Crossed wands held above the marshaller''s head signal the pilot to:','["come forward", "start engines", "slow turn", "stop"]'::jsonb,3,'Stop signal.','original'),
('127.890.d.21.E',3,'A fueler reads the placard near the filler cap and matches the fuel grade and dye color to the engine requirements. She is:','["identifying different grades of aviation fuel and selecting an approved fuel for an aircraft", "using any fuel", "guessing", "ignoring placards"]'::jsonb,0,'Fuel grade.','original'),
('127.890.d.21.E',4,'Aviation gasoline 100LL is dyed:','["green", "blue", "clear", "red"]'::jsonb,1,'100LL blue.','original'),
('127.890.d.21.F',3,'A mechanic grounds the aircraft and fuel truck, then drains a sump sample to look for water and dirt. She is:','["guessing", "painting the sump", "preparing an aircraft for fueling and inspecting an aircraft fuel system for water and contamination", "ignoring fueling"]'::jsonb,2,'Fuel check.','original'),
('127.890.d.21.F',4,'A sample from a fuel drain that shows water bubbles at the bottom means the fuel:','["is the right grade", "is too cool", "is clean", "has water contamination"]'::jsonb,3,'Water in fuel.','original'),
('127.890.d.21.G',3,'A mechanic works through the checklist to start up and shut down a turbine engine in the correct order. She is:','["following a checklist to start up or shut down an aircraft reciprocating or turbine engine", "skipping the list", "painting the engine", "guessing steps"]'::jsonb,0,'Start checklist.','original'),
('127.890.d.21.G',4,'Following the start checklist in order helps prevent:','["better starts", "hot starts and engine damage", "louder starts", "longer starts"]'::jsonb,1,'Order matters.','original'),
('127.890.d.21.H',3,'An engine backfires and flames appear in the induction system, so the mechanic keeps the engine turning to pull the fire through. She is:','["guessing", "ignoring flames", "identifying procedures for extinguishing fires in an engine induction system", "painting the intake"]'::jsonb,2,'Induction fire.','original'),
('127.890.d.21.H',4,'To put out an induction fire during a start, the engine should be:','["stopped and fueled", "shut off at once", "left running idle", "kept cranking to draw the fire into the engine"]'::jsonb,3,'Keep cranking.','original'),
('127.890.d.21.I',3,'A mechanic looks up and follows the correct steps to tie down and secure a turboprop after a ground run. She is:','["securing an aircraft by locating and following the correct procedures for a turbine engine", "guessing", "painting tie-downs", "ignoring steps"]'::jsonb,0,'Securing.','original'),
('127.890.d.21.I',4,'Securing a parked aircraft outdoors normally includes:','["open doors", "chocks, tie-downs and control locks", "no chocks", "loose ropes only"]'::jsonb,1,'Secure steps.','original'),
('127.890.d.21.J',3,'A mechanic opens the manual to the steps for securing a turbine airplane after engine shutdown and cooling. She is:','["guessing", "painting the airplane", "locating and explaining procedures for securing a turbine-powered aircraft after engine shutdown", "ignoring the manual"]'::jsonb,2,'After shutdown.','original'),
('127.890.d.21.J',4,'After shutting down a turbine engine, it is usually:','["covered while hot", "left hot and open", "filled with oil", "allowed to cool and the inlets and exhausts covered"]'::jsonb,3,'Cooldown.','original'),
('127.890.d.22.A',3,'A student learns that washing an aircraft removes salt, dirt and exhaust residue so that damage can be seen. She is:','["explaining the need for aircraft cleaning procedures", "avoiding cleaning", "describing seats", "describing tires"]'::jsonb,0,'Cleaning.','original'),
('127.890.d.22.A',4,'Cleaning an aircraft helps maintenance because it:','["hides cracks", "exposes cracks, leaks and corrosion", "removes parts", "adds weight"]'::jsonb,1,'Why clean.','original'),
('127.890.d.22.B',3,'A student studies how moisture and an electrolyte cause aluminum to corrode into white powder, and what prevents it. She is:','["describing tires", "ignoring corrosion", "explaining corrosion theory, including types and effects of corrosion and corrosion-prone areas", "describing seats"]'::jsonb,2,'Corrosion theory.','original'),
('127.890.d.22.B',4,'Corrosion needs, along with metal, an electrolyte and:','["a magnet", "dry air only", "a vacuum", "an electrical path between areas"]'::jsonb,3,'Corrosion cell.','original'),
('127.890.d.22.C',3,'A mechanic probes a white powdery spot on an aluminum skin, measures the pit depth and plans how to remove it. She is:','["describing corrosion identification and inspection techniques, and corrosion removal and treatment", "guessing", "ignoring corrosion", "painting over"]'::jsonb,0,'Treat corrosion.','original'),
('127.890.d.22.C',4,'Corrosion on aluminum is first removed, then the area is:','["painted only", "treated and given protective coating", "polished only", "left bare"]'::jsonb,1,'Treat and coat.','original'),
('127.890.d.22.D',3,'A shop reviews the nozzle pressure and distance used with a pressure washer so that seals and bearings are not forced open. They are:','["describing seats", "describing tires", "describing the use of high-pressure application equipment", "ignoring pressure"]'::jsonb,2,'Pressure washers.','original'),
('127.890.d.22.D',4,'Aiming a high-pressure spray directly at bearings and seals can:','["cool them", "help them", "remove all wear", "force water or cleaner into places it should not be"]'::jsonb,3,'Spray risk.','original'),
('127.890.d.22.E',3,'A student reads that a strong alkaline cleaner left on aluminum or an acidic cleaner on a composite panel can attack the surface. She is:','["identifying and discussing the effects of improper use of cleaners on aluminum or composite surfaces", "describing seats", "describing tires", "ignoring cleaners"]'::jsonb,0,'Cleaner misuse.','original'),
('127.890.d.22.E',4,'Using a cleaner not approved for the material can cause:','["a longer life", "etching or damage to the surface", "stronger paint", "better shine always"]'::jsonb,1,'Wrong cleaner.','original'),
('127.890.d.22.F',3,'A mechanic uses a barrier coating between aluminum and a steel fitting so that the metals do not touch and corrode. She is:','["describing seats", "describing tires", "explaining accelerated corrosion caused by dissimilar metals and the role of protective coatings", "ignoring metals"]'::jsonb,2,'Dissimilar metals.','original'),
('127.890.d.22.F',4,'A protective coating between two dissimilar metals helps by:','["removing paint", "adding voltage", "adding heat", "keeping them from forming a corrosion cell"]'::jsonb,3,'Barrier.','original'),
('127.890.d.22.G',3,'A painter picks an epoxy primer and a polyurethane topcoat and etches and cleans the aluminum before spraying. She is:','["identifying topcoat materials and discussing concerns regarding surface preparation for finishing", "describing tires", "ignoring paint", "describing seats"]'::jsonb,0,'Topcoat prep.','original'),
('127.890.d.22.G',4,'If a surface is not cleaned and prepared before painting, the paint may:','["stick better", "peel or fail early", "last longer", "dry faster"]'::jsonb,1,'Poor prep.','original'),
('127.890.d.22.H',3,'A painter reads that fumes from solvents and isocyanate paints can harm the lungs and wears a respirator and gloves. She is:','["describing tires", "ignoring fumes", "identifying health concerns when using paints, solvents and finishing materials and the protective equipment needed", "describing seats"]'::jsonb,2,'Paint health.','original'),
('127.890.d.22.H',4,'When spraying isocyanate paints, a painter should wear:','["a paper mask", "sandals", "no mask", "a supplied-air respirator and protective clothing"]'::jsonb,3,'Respirator.','original'),
('127.890.d.23.A',3,'A student sorts anodize, chromate conversion coating, plating and paint as protective finishes for metal. She is:','["identifying types of protective finishes", "describing tires", "describing seats", "ignoring finishes"]'::jsonb,0,'Finish types.','original'),
('127.890.d.23.A',4,'Anodizing protects aluminum by:','["removing metal", "building a hard oxide layer on its surface", "adding heat", "adding weight"]'::jsonb,1,'Anodize.','original'),
('127.890.d.23.B',3,'A mechanic checks a painted wing for blisters and bubbles and picks the right corrosion inhibitor to treat the damage. She is:','["ignoring finish", "guessing", "inspecting finishes for corrosion and identifying, selecting and using aircraft corrosion control materials", "painting over"]'::jsonb,2,'Finish inspect.','original'),
('127.890.d.23.B',4,'Filiform corrosion shows up under paint as:','["a dry film", "bright dots", "smooth gloss", "thread-like tracks"]'::jsonb,3,'Filiform.','original'),
('127.890.d.23.C',3,'A mechanic applies a coat of corrosion-preventive compound after cleaning and treating a repaired panel. She is:','["applying aircraft corrosion prevention and coating materials", "painting by guess", "skipping the step", "ignoring coatings"]'::jsonb,0,'Apply coating.','original'),
('127.890.d.23.C',4,'Corrosion-preventive coatings are applied to:','["dirty surfaces", "clean, treated surfaces", "oily rags", "wet corrosion"]'::jsonb,1,'Clean first.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
